// Campaign table — mirrors docs/funnel-emails.md. Segment names come from contacts/contacts.csv.
const T = {
  A1: { segment: 'buyers', template: 'a1', subject: 'The pops got better since you left 🍉', preview: 'New flavors, same real fruit — and a way to never run out.' },
  A2: { segment: 'buyers', template: 'a2', subject: 'One case = your whole event, sorted',    preview: '$53.50 for 24 pops. Offices, parties, teams, schools.' },
  B1: { segment: 'b2b',    template: 'b1', subject: 'A $2 pop your customers will pay $4 for', preview: 'All-natural, Atlanta-made, margin at every level.' },
  B2: { segment: 'b2b',    template: 'b2', subject: '120 cases, 3,000 pops, one Atlanta afternoon', preview: 'The activation playbook — staffed cart included.' },
  B3: { segment: 'b2b',    template: 'b3', subject: 'Should I close your file?',              preview: 'One reply gets you the price sheet — or a call.' },
};
const cfg = $input.first().json;
const c = T[cfg.campaign];
if (!c) throw new Error(`Unknown campaign ${cfg.campaign}. Use one of ${Object.keys(T).join(', ')}`);
return [{ json: { ...cfg, ...c, template_path: `${cfg.templates_dir}/funnel-${c.template}-template.html` } }];

// Segment filter + suppression + "already got this campaign" memory + daily cap.
const cfg = $('Resolve campaign').first().json;
const sd = $getWorkflowStaticData('global');
sd.sent = sd.sent || {};
const sent = sd.sent[cfg.campaign] = sd.sent[cfg.campaign] || {};
const rows = $input.all().map(i => i.json);
const eligible = rows.filter(r =>
  (r.segment || '').toLowerCase() === cfg.segment &&
  (r.status || 'active') === 'active' &&
  r.email && !sent[r.email.toLowerCase()]
);
const batch = eligible.slice(0, cfg.daily_cap);
console.log(`${cfg.campaign}: ${rows.length} contacts, ${eligible.length} eligible & unsent, sending ${batch.length} (dry_run=${cfg.dry_run})`);
return batch.map(r => ({ json: { ...r, email: r.email.toLowerCase(), remaining_after_this_batch: eligible.length - batch.length } }));

const cfg = $('Resolve campaign').first().json;
const sd = $getWorkflowStaticData('global');
const sent = (sd.sent && sd.sent[cfg.campaign]) || {};
const all = Object.values(sent);
return [{ json: { campaign: cfg.campaign, sent_total_all_time: all.filter(x => x.ok).length, failed_total: all.filter(x => !x.ok).length, dry_run: cfg.dry_run } }];

const r = $('Render email').first().json;
const out = $input.first().json || {};
const ok = !out.error;
const sd = $getWorkflowStaticData('global');
sd.sent = sd.sent || {}; sd.sent[r.campaign] = sd.sent[r.campaign] || {};
const rec = { at: new Date().toISOString(), campaign: r.campaign, email: r.email, segment: r.segment, ok, error: ok ? null : (out.error.message || JSON.stringify(out.error)) };
sd.sent[r.campaign][r.email] = rec;
return [{ json: { ...rec, log_b64: Buffer.from(JSON.stringify(rec) + '\n').toString('base64') } }];
